INSERT INTO "public"."amex_category" ("amex_category_id", "name", "description", "created_at") VALUES
	('d0c71e5c-e864-4a55-85a5-b84286275abe', 'Global Restaurants', 'Purchases at restaurants located in the U.S. and worldwide. Excludes bars, nightclubs, bakeries, caterers, breweries, and restaurants located within hotels, casinos, or event venues. Used by Amex Gold Card for 4x rewards.', '2026-03-16 19:54:19.293045+00'),
	('4f58e1c0-2b42-4531-a6b3-3601c7350385', 'U.S. Supermarkets', 'Purchases at U.S. supermarkets offering a wide variety of food and household products. Excludes superstores (Walmart, Target), warehouse clubs (Costco, BJ''s), convenience stores, specialty stores (bakeries, butchers, liquor stores), and meal-kit delivery services (Blue Apron, HelloFresh).', '2026-03-16 19:54:19.293045+00'),
	('405fd1d6-18ee-47be-887d-a21cfc7946b5', 'Airfare', 'Airfare purchased directly from a passenger airline or through AmexTravel.com for a scheduled flight. Excludes vacation packages, charter flights, private jet flights, and airfare purchased through third-party travel agents.', '2026-03-16 19:54:19.293045+00'),
	('f34fd7dd-60b4-43a5-82e3-039e8740208e', 'Hotels', 'Hotel stays purchased directly with the hotel. Excludes timeshares, banquets, events, vacation packages, and hotel rooms prepaid through third-party travel agents or online travel sites.', '2026-03-16 19:54:19.293045+00'),
	('b9cf06ac-def2-434c-a3c4-605b2f014cac', 'Transit', 'Purchases at merchants whose primary business is transit, including trains, taxis, rideshare services, ferries, tolls, parking, buses, and subways. Excludes airfare, car rentals, and cruises.', '2026-03-16 19:54:19.293045+00'),
	('699c5304-67ff-4cc8-8004-58c6bad2807d', 'U.S. Gas Stations', 'Purchases at U.S. gas stations whose primary business is selling gasoline to consumers. Excludes superstores (Walmart, Target), supermarkets, and warehouse clubs that sell gasoline. Known limitation: exclusion rules are not enforced at the MCC level.', '2026-03-16 19:54:19.293045+00'),
	('87c9f2ce-c769-4ff9-a28d-196cfa8e9d3a', 'U.S. Online Retail', 'Purchases made on a website or app from a U.S. retail merchant that sells physical goods directly to consumers. Excludes restaurants, supermarkets, gas stations, travel, entertainment, streaming, and rideshare services. Known limitation: Amex enforces this via merchant enrollment in addition to MCC — MCC-only matching is an approximation.', '2026-03-16 19:54:19.293045+00');
