	('8d904c8a-5c24-48a3-85ee-8f7b57de0069', 'a4478d5c-84e5-47f1-bb4e-1ceeb8769333', 'Monthly Uber Cash', 'Up to $10 in Uber Cash per month for use on Uber and Uber Eats in the U.S. Must have linked Amex Gold to Uber account.', 10.00, '2026-03-17 00:17:02.61075+00', 'dollars', 'merchant', 'monthly'),
	('0b0a1ebc-c34c-47c3-a09b-15b33208e791', 'a4478d5c-84e5-47f1-bb4e-1ceeb8769333', 'Monthly Dunkin'' Credit', 'Up to $7 in statement credits per month for purchases at U.S. Dunkin'' locations.', 7.00, '2026-03-17 00:17:02.61075+00', 'dollars', 'merchant', 'monthly'),
	('6c41ae5b-0a0d-4ea3-9bfa-e402192a54c5', 'a4478d5c-84e5-47f1-bb4e-1ceeb8769333', 'Resy Credit', 'Up to $50 in statement credits per semi-annual period for purchases at restaurants booked through Resy. Resets January 1 and July 1 each year.', 50.00, '2026-03-17 00:17:02.61075+00', 'dollars', 'merchant', 'semi_annual');
